CREATE TYPE "Role" AS ENUM ('CUSTOMER','WORKER','ADMIN');
CREATE TYPE "AvailabilityStatus" AS ENUM ('AVAILABLE','BUSY','UNAVAILABLE');
CREATE TYPE "VerificationStatus" AS ENUM ('PENDING','VERIFIED','REJECTED');
CREATE TYPE "JobStatus" AS ENUM ('OPEN','ACCEPTED','IN_PROGRESS','COMPLETED','CUSTOMER_CONFIRMED','CANCELLED');
CREATE TYPE "Urgency" AS ENUM ('LOW','NORMAL','HIGH','URGENT');
CREATE TYPE "ReviewStatus" AS ENUM ('PENDING','APPROVED','REJECTED');
CREATE TABLE "User" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),"name" TEXT NOT NULL,"email" TEXT NOT NULL UNIQUE,"passwordHash" TEXT NOT NULL,"role" "Role" NOT NULL DEFAULT 'CUSTOMER',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "WorkerProfile" ("userId" UUID PRIMARY KEY,"displayName" TEXT NOT NULL,"serviceCategories" TEXT[] NOT NULL,"serviceAreaText" TEXT NOT NULL,"latitude" DOUBLE PRECISION,"longitude" DOUBLE PRECISION,"availabilityStatus" "AvailabilityStatus" NOT NULL DEFAULT 'UNAVAILABLE',"verificationStatus" "VerificationStatus" NOT NULL DEFAULT 'PENDING',CONSTRAINT "WorkerProfile_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE);
CREATE TABLE "WorkerCredential" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),"workerId" UUID NOT NULL,"credentialType" TEXT NOT NULL,"offChainFileReference" TEXT NOT NULL,"contentHash" TEXT NOT NULL,"reviewStatus" "ReviewStatus" NOT NULL DEFAULT 'PENDING',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "WorkerCredential_workerId_fkey" FOREIGN KEY ("workerId") REFERENCES "WorkerProfile"("userId") ON DELETE CASCADE);
CREATE TABLE "Job" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),"customerId" UUID NOT NULL,"description" TEXT NOT NULL,"category" TEXT NOT NULL,"categoryConfidence" DOUBLE PRECISION,"locationText" TEXT NOT NULL,"latitude" DOUBLE PRECISION,"longitude" DOUBLE PRECISION,"urgency" "Urgency" NOT NULL DEFAULT 'NORMAL',"status" "JobStatus" NOT NULL DEFAULT 'OPEN',"assignedWorkerId" UUID,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Job_customerId_fkey" FOREIGN KEY ("customerId") REFERENCES "User"("id"),CONSTRAINT "Job_assignedWorkerId_fkey" FOREIGN KEY ("assignedWorkerId") REFERENCES "WorkerProfile"("userId"));
CREATE TABLE "JobEvent" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),"jobId" UUID NOT NULL,"priorStatus" "JobStatus","newStatus" "JobStatus" NOT NULL,"actorId" UUID NOT NULL,"timestamp" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"blockchainTxHash" TEXT,CONSTRAINT "JobEvent_jobId_fkey" FOREIGN KEY ("jobId") REFERENCES "Job"("id") ON DELETE CASCADE,CONSTRAINT "JobEvent_actorId_fkey" FOREIGN KEY ("actorId") REFERENCES "User"("id"));
CREATE TABLE "Review" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),"jobId" UUID NOT NULL UNIQUE,"customerId" UUID NOT NULL,"workerId" UUID NOT NULL,"rating" INTEGER NOT NULL,"comment" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "Review_jobId_fkey" FOREIGN KEY ("jobId") REFERENCES "Job"("id"),CONSTRAINT "Review_customerId_fkey" FOREIGN KEY ("customerId") REFERENCES "User"("id"),CONSTRAINT "Review_workerId_fkey" FOREIGN KEY ("workerId") REFERENCES "WorkerProfile"("userId"));
CREATE TABLE "BlockchainTransaction" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),"recordType" TEXT NOT NULL,"recordId" UUID NOT NULL,"txHash" TEXT NOT NULL,"chainId" BIGINT NOT NULL,"contractAddress" TEXT NOT NULL,"status" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "User_role_idx" ON "User"("role");
CREATE INDEX "WorkerProfile_availabilityStatus_verificationStatus_idx" ON "WorkerProfile"("availabilityStatus","verificationStatus");
CREATE INDEX "WorkerCredential_workerId_reviewStatus_idx" ON "WorkerCredential"("workerId","reviewStatus");
CREATE INDEX "Job_category_status_idx" ON "Job"("category","status");
CREATE INDEX "Job_customerId_createdAt_idx" ON "Job"("customerId","createdAt");
CREATE INDEX "Job_assignedWorkerId_status_idx" ON "Job"("assignedWorkerId","status");
CREATE INDEX "JobEvent_jobId_timestamp_idx" ON "JobEvent"("jobId","timestamp");
CREATE INDEX "Review_workerId_createdAt_idx" ON "Review"("workerId","createdAt");
ALTER TABLE "BlockchainTransaction" ADD CONSTRAINT "BlockchainTransaction_recordId_fkey" FOREIGN KEY ("recordId") REFERENCES "Job"("id") ON DELETE CASCADE;
CREATE INDEX "BlockchainTransaction_recordType_recordId_idx" ON "BlockchainTransaction"("recordType","recordId");
CREATE INDEX "WorkerProfile_categories_gin_idx" ON "WorkerProfile" USING GIN ("serviceCategories");
ALTER TABLE "Job" ADD COLUMN "preferredWorkerId" UUID;
CREATE INDEX "Job_preferredWorkerId_idx" ON "Job"("preferredWorkerId");
